begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions, pg_temp;
-- These grants exist only in this rolled-back test transaction, for assertions
-- executed under actual API roles, never as part of the production migrations.
do $$ declare f record; begin
  for f in select p.oid::regprocedure as signature from pg_proc p join pg_depend d on d.objid=p.oid join pg_extension e on e.oid=d.refobjid where e.extname='pgtap' and d.deptype='e' loop
    execute format('grant execute on function %s to authenticated, anon',f.signature);
  end loop;
end $$;
grant usage on schema extensions to authenticated,anon;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values
 ('00000000-0000-0000-0000-000000000001','owner@example.test',now(),false),
 ('00000000-0000-0000-0000-000000000002','member@example.test',now(),false),
 ('00000000-0000-0000-0000-000000000003','outsider@example.test',now(),false),
 ('00000000-0000-0000-0000-000000000004','unverified@example.test',null,false);
create temporary table fixture(key text primary key,value jsonb);
grant all on fixture to authenticated,anon;

select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relname in ('reserves','reserve_members','products','product_stock','shopping_items','invitations','requests','scan_operations') and c.relrowsecurity),8::bigint,'RLS enabled on all application tables');
select ok(not has_table_privilege('authenticated','public.product_stock','UPDATE'),'No direct stock update grant');
select ok(not has_table_privilege('authenticated','public.reserve_members','INSERT'),'No self membership insert');
select ok(not has_table_privilege('authenticated','private.requests','SELECT'),'Journal is private');
select ok(not has_function_privilege('anon','public.mutate_reserve(uuid,uuid,text,jsonb)','EXECUTE'),'Anonymous cannot execute mutations');
select ok(not has_function_privilege('authenticated','private.lock_reserve(uuid)','EXECUTE'),'Internal privileged helper not executable');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prosecdef and not coalesce(p.proconfig @> array['search_path=""'],false)),'Every privileged function pins an empty search_path');

set local role anon;
select throws_ok('select * from public.product_stock','42501',null,'Anonymous stock read denied');
select throws_ok($$select public.create_reserve(gen_random_uuid(),'No auth')$$,'42501',null,'Anonymous reserve creation denied');
reset role;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-000000000004","role":"authenticated"}';
set local role authenticated;
select throws_ok($$select public.create_reserve(gen_random_uuid(),'Unverified')$$,'42501',null,'Unverified account denied');
reset role;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-000000000001","role":"authenticated"}';
set local role authenticated;
insert into fixture values ('reserve',public.create_reserve('10000000-0000-0000-0000-000000000001','Test reserve'));
select is((select count(*) from public.reserves),1::bigint,'Owner sees own reserve');
select is((select role from public.reserve_members where user_id=auth.uid()),'owner','Creator is owner');
select is(public.create_reserve('10000000-0000-0000-0000-000000000001','Test reserve'),(select value from fixture where key='reserve'),'Reserve creation replay is idempotent');
select throws_ok($$select public.create_reserve('10000000-0000-0000-0000-000000000001','Different')$$,'22023',null,'Same key with different parameters rejected');
select throws_ok($$insert into public.reserve_members(reserve_id,user_id,role) select id,'00000000-0000-0000-0000-000000000003','owner' from public.reserves$$,'42501',null,'Cannot inject another owner');
insert into fixture values ('invite',public.invite_member('10000000-0000-0000-0000-000000000002',(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'member@example.test'));
select is(public.invite_member('10000000-0000-0000-0000-000000000002',(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'member@example.test')->'token','null'::jsonb,'Invitation retry never exposes a stored plaintext token');
select throws_ok('select * from private.invitations','42501',null,'Owner cannot read invitation hashes');
reset role;
select ok(not exists(select 1 from private.requests where response::text like '%'||(select value->>'token' from fixture where key='invite')||'%' or parameters::text like '%'||(select value->>'token' from fixture where key='invite')||'%'),'Invitation secret never stored in request journal');
select ok((select token_hash from private.invitations where id=(select (value->>'invitation_id')::uuid from fixture where key='invite')) = extensions.digest((select value->>'token' from fixture where key='invite'),'sha256'),'Only a cryptographic digest is stored');

set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-000000000003","role":"authenticated"}';
set local role authenticated;
select is((select count(*) from public.reserves),0::bigint,'Outsider cannot see reserve');
select is(public.get_reserve_snapshot((select (value->>'reserve_id')::uuid from fixture where key='reserve')),null::jsonb,'Outsider snapshot returns no data');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'create_product','{"name":"Injected"}')$$,'42501',null,'Outsider mutation denied');
select throws_ok($$select public.accept_invitation(gen_random_uuid(),(select (value->>'invitation_id')::uuid from fixture where key='invite'),(select value->>'token' from fixture where key='invite'))$$,'P0001',null,'Valid token cannot be used by wrong account');
insert into fixture values ('other_reserve',public.create_reserve(gen_random_uuid(),'Other household'));
reset role;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-000000000002","role":"authenticated","user_metadata":{"role":"owner"}}';
set local role authenticated;
select throws_ok($$select public.accept_invitation(gen_random_uuid(),(select (value->>'invitation_id')::uuid from fixture where key='invite'),'wrong')$$,'P0001',null,'Wrong invitation secret rejected');
reset role;
update private.invitations set expires_at=now()-interval '1 second' where id=(select (value->>'invitation_id')::uuid from fixture where key='invite');
set local role authenticated;
select throws_ok($$select public.accept_invitation(gen_random_uuid(),(select (value->>'invitation_id')::uuid from fixture where key='invite'),(select value->>'token' from fixture where key='invite'))$$,'P0001',null,'Expired invitation rejected');
reset role;
update private.invitations set expires_at=now()+interval '1 hour' where id=(select (value->>'invitation_id')::uuid from fixture where key='invite');
set local role authenticated;
insert into fixture values ('accepted',public.accept_invitation('10000000-0000-0000-0000-000000000003',(select (value->>'invitation_id')::uuid from fixture where key='invite'),(select value->>'token' from fixture where key='invite')));
select is((select count(*) from public.reserve_members),2::bigint,'Second member joins same reserve');
select is((select role from public.reserve_members where user_id=auth.uid()),'member','Untrusted metadata cannot grant owner role');
select is(public.accept_invitation('10000000-0000-0000-0000-000000000003',(select (value->>'invitation_id')::uuid from fixture where key='invite'),(select value->>'token' from fixture where key='invite')),(select value from fixture where key='accepted'),'Same acceptance request replays without double membership');
select throws_ok($$select public.accept_invitation(gen_random_uuid(),(select (value->>'invitation_id')::uuid from fixture where key='invite'),(select value->>'token' from fixture where key='invite'))$$,'P0001',null,'Used invitation rejected with new request');
select throws_ok($$select public.invite_member(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'outsider@example.test')$$,'42501',null,'Ordinary member cannot invite or escalate');
reset role;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-000000000001","role":"authenticated"}';
set local role authenticated;
select throws_ok($$select public.invite_member(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'outsider@example.test')$$,'23514',null,'Owner cannot invite a third member');
reset role;
select throws_ok($$insert into public.reserve_members values ((select (value->>'reserve_id')::uuid from fixture where key='reserve'),'00000000-0000-0000-0000-000000000003','member',now())$$,'23514',null,'Database trigger also enforces capacity');
set local role authenticated;

insert into fixture values ('product',public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'create_product','{"id":"00000000-0000-0000-0000-000000000101","name":"Thon test","barcode":"1234567890128","minimum":2}'));
select is((select quantity from public.product_stock),0,'Catalogue creation creates a distinct zero-stock row');
select is((select count(*) from public.shopping_items),0::bigint,'Minimum threshold never adds shopping automatically');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'create_product','{"name":"Duplicate","barcode":"1234567890128"}')$$,'23505',null,'Barcode unique inside reserve');
reset role;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-000000000003","role":"authenticated"}';
set local role authenticated;
select lives_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='other_reserve'),'create_product','{"name":"Same barcode in other reserve","barcode":"1234567890128"}')$$,'Barcode can coexist in two different households');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='other_reserve'),'add_shopping','{"product_id":"00000000-0000-0000-0000-000000000101","quantity":1}')$$,'P0002',null,'Member of another reserve cannot link a foreign product by changing its id');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='other_reserve'),'stock','{"product_id":"00000000-0000-0000-0000-000000000101","delta":1}')$$,'P0002',null,'Member of another reserve cannot mutate a foreign product by changing its id');
reset role;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-000000000001","role":"authenticated"}';
set local role authenticated;
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'update_product','{"product_id":"00000000-0000-0000-0000-000000000101","quantity":100}')$$,'22023',null,'Stock cannot bypass operation RPC through catalogue fields');
select throws_ok($$update public.product_stock set quantity=100$$,'42501',null,'Direct stock write refused');
select throws_ok($$update public.reserve_members set role='owner'$$,'42501',null,'Direct role escalation refused');
insert into fixture values ('linked',public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'add_shopping','{"product_id":"00000000-0000-0000-0000-000000000101","quantity":5}'));
insert into fixture values ('free',public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'add_shopping','{"name":"Thon test","quantity":7}'));
insert into fixture values ('scan',public.mutate_reserve('20000000-0000-0000-0000-000000000001',(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'scan','{"product_id":"00000000-0000-0000-0000-000000000101","delta":1}'));
select is((select quantity from public.product_stock),1,'First scan adds one');
select is((select quantity from public.shopping_items where product_id is not null),4,'First scan deducts one linked shopping unit');
select is((select quantity from public.shopping_items where product_id is null),7,'Free homonym never deducted');
select is(public.mutate_reserve('20000000-0000-0000-0000-000000000001',(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'scan','{"product_id":"00000000-0000-0000-0000-000000000101","delta":1}'),(select value from fixture where key='scan'),'Scan replay returns exact original result');
select is((select quantity from public.product_stock),1,'Replay does not double stock');
select throws_ok($$select public.mutate_reserve('20000000-0000-0000-0000-000000000001',(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'scan','{"product_id":"00000000-0000-0000-0000-000000000101","delta":2}')$$,'22023',null,'Reusing scan key with different delta rejected');

select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'adjust_scan','{"scan_id":"20000000-0000-0000-0000-000000000001","expected_version":1,"quantity":5}');
select is((select quantity from public.product_stock),5,'Adjustment to five adds total five');
select is((select quantity from public.shopping_items where product_id is not null),0,'Adjustment to five deducts total five');
select ok((select checked from public.shopping_items where product_id is not null),'Completed linked item checked');
select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'adjust_scan','{"scan_id":"20000000-0000-0000-0000-000000000001","expected_version":2,"quantity":3}');
select is((select quantity from public.product_stock),3,'Reduction restores stock delta');
select is((select quantity from public.shopping_items where product_id is not null),2,'Reduction restores shopping delta');
select ok(not (select checked from public.shopping_items where product_id is not null),'Reduction unchecks restored item');
select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'adjust_scan','{"scan_id":"20000000-0000-0000-0000-000000000001","expected_version":3,"quantity":8}');
select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'adjust_scan','{"scan_id":"20000000-0000-0000-0000-000000000001","expected_version":4,"quantity":6}');
select is((select quantity from public.shopping_items where product_id is not null),0,'Reduction above shopping baseline does not invent shopping');
select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'adjust_scan','{"scan_id":"20000000-0000-0000-0000-000000000001","expected_version":5,"quantity":2}');
select is((select quantity from public.shopping_items where product_id is not null),3,'Successive adjustments remain coherent');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'adjust_scan','{"scan_id":"20000000-0000-0000-0000-000000000001","expected_version":6,"quantity":0}')$$,'22023',null,'Use undo, not zero-quantity adjustment');
select public.mutate_reserve('20000000-0000-0000-0000-000000000002',(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'undo_scan','{"scan_id":"20000000-0000-0000-0000-000000000001","expected_version":6}');
select is((select quantity from public.product_stock),0,'Compensating undo restores original stock');
select is((select quantity from public.shopping_items where product_id is not null),5,'Compensating undo restores original shopping');
select is((select count(*) from public.products),1::bigint,'Zero-stock product stays in catalogue');
select public.mutate_reserve('20000000-0000-0000-0000-000000000002',(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'undo_scan','{"scan_id":"20000000-0000-0000-0000-000000000001","expected_version":6}');
select is((select quantity from public.product_stock),0,'Undo replay does not compensate twice');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'undo_scan','{"scan_id":"20000000-0000-0000-0000-000000000001","expected_version":7}')$$,'40001',null,'Cancelled scan cannot be undone again');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'stock','{"product_id":"00000000-0000-0000-0000-000000000101","delta":-1}')$$,'23514',null,'Negative stock rejected');

select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'stock','{"product_id":"00000000-0000-0000-0000-000000000101","delta":9999}');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'stock','{"product_id":"00000000-0000-0000-0000-000000000101","delta":1}')$$,'23514',null,'Stock above 9999 rejected');
select is((select quantity from public.product_stock),9999,'Rejected upper bound leaves stock unchanged');
select is((select quantity from public.shopping_items where product_id is not null),5,'Stock buttons do not alter shopping');
select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'stock','{"product_id":"00000000-0000-0000-0000-000000000101","delta":-9996}');
insert into fixture values ('remove',public.mutate_reserve('20000000-0000-0000-0000-000000000003',(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'scan','{"product_id":"00000000-0000-0000-0000-000000000101","delta":-1}'));
select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'adjust_scan','{"scan_id":"20000000-0000-0000-0000-000000000003","expected_version":1,"quantity":3}');
select is((select quantity from public.product_stock),0,'Remove scan can consume exact available stock');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'adjust_scan','{"scan_id":"20000000-0000-0000-0000-000000000003","expected_version":2,"quantity":4}')$$,'23514',null,'Remove adjustment cannot exceed available stock');
select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'adjust_scan','{"scan_id":"20000000-0000-0000-0000-000000000003","expected_version":2,"quantity":2}');
select is((select quantity from public.product_stock),1,'Reducing remove scan puts one unit back');
select is((select quantity from public.shopping_items where product_id is not null),5,'Remove mode never changes shopping');
select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'stock','{"product_id":"00000000-0000-0000-0000-000000000101","delta":1}');
select throws_ok($$select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'undo_scan','{"scan_id":"20000000-0000-0000-0000-000000000003","expected_version":3}')$$,'40001',null,'Concurrent modification refuses stale undo');
select is((select quantity from public.product_stock),2,'Stale undo preserves newer stock');
reset role;

create function pg_temp.fail_shopping() returns trigger language plpgsql as $$ begin raise exception 'simulated shopping failure'; end $$;
create trigger test_partial_failure before update on public.shopping_items for each row execute function pg_temp.fail_shopping();
set local role authenticated;
select throws_ok($$select public.mutate_reserve('20000000-0000-0000-0000-000000000099',(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'scan','{"product_id":"00000000-0000-0000-0000-000000000101","delta":1}')$$,'P0001',null,'Injected shopping failure aborts scan');
select is((select quantity from public.product_stock),2,'Partial failure rolls stock back');
select is((select quantity from public.shopping_items where product_id is not null),5,'Partial failure preserves shopping');
reset role;
drop trigger test_partial_failure on public.shopping_items;
select is((select count(*) from private.requests where request_id='20000000-0000-0000-0000-000000000099'),0::bigint,'Failed transaction leaves no successful idempotency receipt');
set local role authenticated;
select public.mutate_reserve(gen_random_uuid(),(select (value->>'reserve_id')::uuid from fixture where key='reserve'),'delete_product','{"product_id":"00000000-0000-0000-0000-000000000101"}');
select is((select count(*) from public.products),0::bigint,'Product deleted intentionally');
select is((select count(*) from public.product_stock),0::bigint,'Dependent stock deleted');
select is((select count(*) from public.shopping_items where product_id is null),2::bigint,'Linked shopping detached and preserved as free item');
reset role;
set local request.jwt.claims = '{"sub":"00000000-0000-0000-0000-000000000003","role":"authenticated"}';
set local role authenticated;
select is((select count(*) from public.reserves),1::bigint,'Outsider sees only their own household');
select is((select count(*) from public.shopping_items),0::bigint,'No cross-household shopping leak');
reset role;
select * from finish();
rollback;
